Ruby vs Go:
    
    1. Ruby Example
       class User
           attr_accessor :name, :age
           
           def initialize(name, age)
               @name = name
               @age = age
           end
       end
        
       users = []
       10.times do |i|
           users << User.new('User \#{i}', 20 + i)
       end
        
       users.each { |u| puts u.name }
    
    2. Go Example
       package main
        
       import \"fmt\"
        
       type User struct {
           Name string
           Age  int
       }
        
       func main() {
           users := []User{}
           for i := 0; i < 10; i++ {
               users = append(users, User{
                   Name: fmt.Sprintf(\"User %d\", i),
                   Age:  20 + i,
               })
           }
           
           for _, u := range users {
               fmt.Println(u.Name)
           }
       }
    
    3. Comparison Table
